const char* ssid = "DINA"; // Название вашей сети
const char* password = "12345678"; // Пароль от Wi-Fi

// ================= НАСТРОЙКИ ПИНОВ =================
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// Пины для сервоприводов (поменяйте, если у вас распаяно иначе)
#define PIN_SERVO_FL D5 // Передняя левая
#define PIN_SERVO_FR D6 // Передняя правая
#define PIN_SERVO_BL D7 // Задняя левая
#define PIN_SERVO_BR D8 // Задняя правая
#define PIN_BUZZER D2 // Динамик

Servo servoFL, servoFR, servoBL, servoBR;

// Базовые углы (НАСТРОЙТЕ ПОД СВОЮ МЕХАНИКУ!)
// Чтобы собака стояла ровно, эти углы нужно подобрать индивидуально
int standFL = 90, standFR = 90, standBL = 90, standBR = 90; 
int offset = 25; // Амплитуда шага

ESP8266WebServer server(80);

// ================= ФУНКЦИИ ДЛЯ ЭКРАНА =================
void drawFace(int emotion) {
display.clearDisplay();
display.setTextColor(SSD1306_WHITE);

if (emotion == 1) { // РАДОСТЬ (Глаза ^ ^)
display.drawLine(30, 25, 40, 15, SSD1306_WHITE);
display.drawLine(40, 15, 50, 25, SSD1306_WHITE);
display.drawLine(78, 25, 88, 15, SSD1306_WHITE);
display.drawLine(88, 15, 98, 25, SSD1306_WHITE);
display.drawCircleHelper(64, 35, 15, 3, SSD1306_WHITE); // Улыбка
} 
else if (emotion == 2) { // ГРУСТЬ (Глаза вниз, грустный рот)
display.fillCircle(40, 20, 6, SSD1306_WHITE);
display.fillCircle(88, 20, 6, SSD1306_WHITE);
display.drawLine(45, 40, 64, 35, SSD1306_WHITE); // Рот
display.drawLine(64, 35, 83, 40, SSD1306_WHITE);
display.drawLine(30, 25, 45, 30, SSD1306_WHITE); // Брови
display.drawLine(98, 25, 83, 30, SSD1306_WHITE);
} 
else if (emotion == 3) { // ЗЛОСТЬ (Косые глаза, зубы)
display.drawLine(30, 25, 45, 15, SSD1306_WHITE);
display.drawLine(45, 15, 50, 25, SSD1306_WHITE);
display.drawLine(98, 25, 83, 15, SSD1306_WHITE);
display.drawLine(83, 15, 78, 25, SSD1306_WHITE);
display.drawRect(45, 40, 38, 10, SSD1306_WHITE); // Рот
display.drawLine(45, 45, 83, 45, SSD1306_WHITE); // Зубы
} 
else { // НЕЙТРАЛЬНО (Обычные глаза)
display.fillCircle(40, 20, 6, SSD1306_WHITE);
display.fillCircle(88, 20, 6, SSD1306_WHITE);
display.fillCircle(40, 20, 2, SSD1306_BLACK);
display.fillCircle(88, 20, 2, SSD1306_BLACK);
display.drawLine(50, 40, 78, 40, SSD1306_WHITE); // Прямой рот
}
display.display();
}

// ================= ФУНКЦИИ ДВИЖЕНИЯ =================
void stand() {
servoFL.write(standFL);
servoFR.write(standFR);
servoBL.write(standBL);
servoBR.write(standBR);
drawFace(0); // Нейтральное лицо
}

void walk() {
drawFace(1); // Радостное лицо при ходьбе
for (int i = 0; i < 3; i++) { // Делаем 3 шага
// Диагональная пара 1 (Передняя левая + Задняя правая)
servoFL.write(standFL + offset);
servoBR.write(standBR - offset);
delay(200);
servoFL.write(standFL - offset);
servoBR.write(standBR + offset);
delay(200);

// Диагональная пара 2 (Передняя правая + Задняя левая)
servoFR.write(standFR + offset);
servoBL.write(standBL - offset);
delay(200);
servoFR.write(standFR - offset);
servoBL.write(standBL + offset);
delay(200);
}
stand(); // Возврат в стойку
}

void bark() {
drawFace(3); // Злое лицо
tone(PIN_BUZZER, 800, 100); // Гав
delay(150);
tone(PIN_BUZZER, 600, 150);
delay(300);
noTone(PIN_BUZZER);
stand();
}

// ================= ВЕБ-СЕРВЕР =================
void handleRoot() {
String html = "<html><head><meta name='viewport' content='width=device-width, initial-scale=1.0'><style>body{text-align:center;font-family:Arial;background:#f0f0f0;} button{padding:15px 30px;margin:10px;font-size:18px;border-radius:10px;border:none;background:#4CAF50;color:white;box-shadow:2px 2px 5px #999;} .bark{background:#f44336;} .sad{background:#607d8b;}</style></head><body>";
html += "<h1>Робот-Собака</h1>";
html += "<button onclick=\"location.href='/walk'\">Идти (Радость)</button><br>";
html += "<button class='bark' onclick=\"location.href='/bark'\">Гав!</button>";
html += "<button class='sad' onclick=\"location.href='/sad'\">Грустить</button><br>";
html += "<button onclick=\"location.href='/stand'\">Стоять</button>";
html += "</body></html>";
server.send(200, "text/html", html);
}

void setup() {
Serial.begin(115200);

// Инициализация пинов
pinMode(PIN_BUZZER, OUTPUT);

// Инициализация дисплея
if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
Serial.println(F("SSD1306 allocation failed"));
for(;;);
}

// Подключение сервоприводов
servoFL.attach(PIN_SERVO_FL);
servoFR.attach(PIN_SERVO_FR);
servoBL.attach(PIN_SERVO_BL);
servoBR.attach(PIN_SERVO_BR);
stand(); // Встаем в исходное положение

// Подключение к Wi-Fi
WiFi.begin(ssid, password);
while (WiFi.status() != WL_CONNECTED) {
delay(500);
Serial.print(".");
drawFace(2); // Пока грустим, пока нет сети
}

// Показываем IP-адрес на экране
display.clearDisplay();
display.setTextSize(1);
display.setCursor(0, 0);
display.print("IP: ");
display.print(WiFi.localIP());
display.display();

// Настройка маршрутов сервера
server.on("/", handleRoot);
server.on("/walk", []() { server.send(200, "text/plain", "Walking"); walk(); });
server.on("/bark", []() { server.send(200, "text/plain", "Barking"); bark(); });
server.on("/sad", []() { server.send(200, "text/plain", "Sad"); drawFace(2); });
server.on("/stand", []() { server.send(200, "text/plain", "Standing"); stand(); });

server.begin();
}

void loop() {
server.handleClient();
}
